// ---------------------------------------------------------------------------
// behaviors.generated.ts — generated by nvoos-astro-forge (Proposal 121);
// edits are overwritten on re-scaffold. The source scroll behavior: sticky,
// reveal-on-scroll, and parallax entries keyed by the source section id, plus
// the header-sticky flag. A parallax entry carries its MOVING PIECES (Phlox
// `aux-parallax-piece` depth/origin/off, Elementor motion_fx direction/speed/
// range/devices) — facts only. The template rebuilds the motion with its own
// CSS scroll timeline, never the source's JS.
// ---------------------------------------------------------------------------

export type BehaviorKind = 'sticky' | 'reveal' | 'parallax';
export type RevealEffect = 'fade-up' | 'fade-down' | 'fade-left' | 'fade-right' | 'scale-up' | 'blur' | 'fade';

/** One moving piece inside a parallax band. Phlox `aux-parallax-piece`
 * (`depth`/`origin`/`off`) and Elementor Motion Effects (`direction`/`speed`/
 * `range`/`devices`) both land here. */
export interface ParallaxPiece {
	id?: string;
	src?: string;
	index?: number;
	type?: 'position' | 'background';
	depth?: number;
	origin?: 'top' | 'bottom' | 'middle';
	off?: number;
	direction?: 'negative' | 'positive';
	speed?: number;
	range?: { start?: number; end?: number };
	devices?: string[];
}

export interface ScrollBehaviorEntry {
	id?: string;
	kind: BehaviorKind;
	effect?: RevealEffect;
	speed?: number;
	/** The band's moving pieces, source order (parallax only). */
	pieces?: ParallaxPiece[];
}

export const behaviors: {
	headerSticky: boolean;
	/** The source's own resting `position` — `fixed` means the header floats OVER
	 * the first band instead of holding a row in the flow. */
	headerPosition?: string;
	/** The pinned header's measured state (`analyze --geometry`). Present only
	 * when the source CHANGES the header on scroll. */
	headerPinnedBg?: string;
	headerPinnedInk?: string;
	headerPinnedShadow?: string;
	/** The measured resting and pinned header heights (a shrinking header). */
	headerRestHeight?: string;
	headerPinnedHeight?: string;
	entries: ScrollBehaviorEntry[];
} = {
	entries: [],
	headerSticky: false,
};
